  request_id: requestId,
  agent_id: 'knowledge_fabric_agent',
  status: 'completed',
  output: {
    summary: concept.summary || 'Knowledge Fabric AI Agent completed.',
    created_candidates: [concept],
    review_state: 'review_needed',
